def backfill_processos_carga_inicial(apps, schema_editor):
    Patriarca = apps.get_model("carga_org_lot", "Patriarca")
    Processo = apps.get_model("carga_org_lot", "ProcessoCargaInicial")
    Historico = apps.get_model(
        "carga_org_lot",
        "HistoricoProcessoCargaInicial",
    )
    Importacao = apps.get_model("carga_org_lot", "ImportacaoPlanilha")

    for patriarca in Patriarca.objects.all().iterator():
        importacoes = Importacao.objects.filter(idpatriarca_id=patriarca.pk)
        possui_lotacao = importacoes.filter(idtipocarga_id__in=(4, 5)).exists()
        possui_organograma = importacoes.filter(idtipocarga_id=3).exists()

        if possui_lotacao:
            fase = "PREPARANDO_LOTACOES"
            status_organograma = "PRONTO"
            status_lotacao = "EM_PREPARACAO"
        elif possui_organograma:
            fase = "PREPARANDO_ORGANOGRAMA"
            status_organograma = "EM_PREPARACAO"
            status_lotacao = "NAO_INICIADA"
        else:
            fase = "NOVO"
            status_organograma = "NAO_INICIADO"
            status_lotacao = "BLOQUEADA"

        processo = Processo.objects.create(
            idpatriarca_id=patriarca.pk,
            strfaseatual=fase,
            strstatusorganograma=status_organograma,
            strstatuslotacao=status_lotacao,
            flgativo=True,
        )
        importacoes.update(
            idprocessocargainicial_id=processo.pk,
            strstatusimportacao="INCORPORADA",
        )
        Historico.objects.create(
            idprocessocargainicial_id=processo.pk,
            stracao="PROCESSO_MIGRADO",
            strfasenova=fase,
            strstatusorganogramanovo=status_organograma,
            strstatuslotacaonovo=status_lotacao,
            strmensagem=(
                "Processo criado automaticamente a partir dos dados existentes."
            ),
        )


